import { describe, expect, it } from "vitest";
import vectors from "@/test/fixtures/log2-bounds-vectors.json";
import { log2Bounds } from "./math";

/** Generated by script/GenerateLogBoundsVectors.s.sol from the real Solidity Log2Bounds library. */
describe("Solidity Log2Bounds differential vectors", () => {
  it("covers the full compiler-generated corpus", () => {
    expect(vectors).toHaveLength(631);
    expect(vectors.every((vector) => vector.kind === "log")).toBe(true);
    expect(new Set(vectors.map((vector) => vector.input)).size).toBe(607);
    expect(vectors.map((vector) => vector.input)).toContain("667601134098543439318150072872112656");
  });

  for (const vector of vectors)
    it(`matches Solidity logarithm bounds for ${vector.input}`, () => {
      expect(log2Bounds(BigInt(vector.input))).toEqual([
        BigInt(vector.lower),
        BigInt(vector.upper),
      ]);
    });
});
